import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  FiAward,
  FiCheck,
  FiEdit2,
  FiImage,
  FiPlus,
  FiRefreshCw,
  FiSearch,
  FiStar,
  FiTrash2,
  FiUser,
  FiX,
} from "react-icons/fi";

import api from "../../services/api";
import { useLanguage } from "../../contexts/LanguageContext";

const EMPTY_FORM = {
  name_en: "",
  name_km: "",
  role_en: "",
  role_km: "",
  company_en: "",
  company_km: "",
  story_en: "",
  story_km: "",
  image: "",
  graduation_year: "",
  is_featured: false,
  is_active: true,
  order: 0,
};

const AdminAlumni = () => {
  const { t, language } = useLanguage();
  const isKhmer = language === "km" || language === "kh";

  const tr = (key, english, khmer) => {
    const translated = typeof t === "function" ? t(key) : "";

    if (
      translated &&
      translated !== key &&
      !String(translated).includes("undefined")
    ) {
      return translated;
    }

    return isKhmer ? khmer : english;
  };

  const localized = (item, field, fallback = "") => {
    if (!item) return fallback;

    const selectedField = `${field}_${isKhmer ? "km" : "en"}`;
    const value = item[selectedField];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ""
    ) {
      return value;
    }

    return fallback;
  };

  const [alumni, setAlumni] = useState([]);
  const [formData, setFormData] = useState(EMPTY_FORM);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [deletingId, setDeletingId] = useState(null);

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [featuredFilter, setFeaturedFilter] = useState("all");

  const [editingId, setEditingId] = useState(null);
  const [showForm, setShowForm] = useState(false);

  const [message, setMessage] = useState({
    type: "",
    text: "",
  });

  const API_BASE_URL =
    process.env.REACT_APP_API_URL || "http://127.0.0.1:8000";

  const getImageUrl = (path) => {
    if (!path) return "";

    if (
      String(path).startsWith("http://") ||
      String(path).startsWith("https://")
    ) {
      return path;
    }

    if (String(path).startsWith("/")) {
      return `${API_BASE_URL}${path}`;
    }

    return `${API_BASE_URL}/${path}`;
  };

  const showMessage = (type, text) => {
    setMessage({ type, text });

    window.clearTimeout(showMessage.timer);

    showMessage.timer = window.setTimeout(() => {
      setMessage({ type: "", text: "" });
    }, 4000);
  };

  const getApiErrorMessage = (error) => {
    const detail = error?.response?.data?.detail;

    if (Array.isArray(detail)) {
      return detail
        .map((item) => item?.msg || item)
        .filter(Boolean)
        .join(", ");
    }

    if (typeof detail === "string") {
      return detail;
    }

    return (
      error?.response?.data?.message ||
      error?.message ||
      tr("alumni.operationFailed", "Something went wrong. Please try again.", "មានបញ្ហាកើតឡើង។ សូមព្យាយាមម្ដងទៀត។")
    );
  };

  const fetchAlumni = useCallback(async () => {
    try {
      setLoading(true);

      /*
       * Admin endpoint returns active and inactive records.
       * Authorization is expected to be added by your shared api instance.
       */
      const response = await api.get("/api/alumni/admin/all", {
        params: {
          skip: 0,
          limit: 200,
        },
      });

      const data = Array.isArray(response.data)
        ? response.data
        : Array.isArray(response.data?.items)
        ? response.data.items
        : [];

      setAlumni(data);
    } catch (error) {
      console.error("Fetch alumni error:", error);
      showMessage("error", getApiErrorMessage(error));
      setAlumni([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchAlumni();
  }, [fetchAlumni]);

  const filteredAlumni = useMemo(() => {
    const keyword = search.trim().toLowerCase();

    return alumni.filter((item) => {
      const searchableText = [
        item.name_en,
        item.name_km,
        item.role_en,
        item.role_km,
        item.company_en,
        item.company_km,
        item.graduation_year,
      ]
        .filter((value) => value !== null && value !== undefined)
        .join(" ")
        .toLowerCase();

      const matchesSearch =
        keyword === "" || searchableText.includes(keyword);

      const matchesStatus =
        statusFilter === "all" ||
        (statusFilter === "active" && item.is_active) ||
        (statusFilter === "inactive" && !item.is_active);

      const matchesFeatured =
        featuredFilter === "all" ||
        (featuredFilter === "featured" && item.is_featured) ||
        (featuredFilter === "regular" && !item.is_featured);

      return matchesSearch && matchesStatus && matchesFeatured;
    });
  }, [alumni, search, statusFilter, featuredFilter]);

  const stats = useMemo(() => {
    return {
      total: alumni.length,
      active: alumni.filter((item) => item.is_active).length,
      featured: alumni.filter((item) => item.is_featured).length,
      inactive: alumni.filter((item) => !item.is_active).length,
    };
  }, [alumni]);

  const resetForm = () => {
    setFormData(EMPTY_FORM);
    setEditingId(null);
    setShowForm(false);
  };

  const openCreateForm = () => {
    setFormData(EMPTY_FORM);
    setEditingId(null);
    setShowForm(true);
  };

  const openEditForm = (item) => {
    setEditingId(item.id);

    setFormData({
      name_en: item.name_en || "",
      name_km: item.name_km || "",
      role_en: item.role_en || "",
      role_km: item.role_km || "",
      company_en: item.company_en || "",
      company_km: item.company_km || "",
      story_en: item.story_en || "",
      story_km: item.story_km || "",
      image: item.image || "",
      graduation_year:
        item.graduation_year !== null &&
        item.graduation_year !== undefined
          ? String(item.graduation_year)
          : "",
      is_featured: Boolean(item.is_featured),
      is_active:
        item.is_active === undefined ? true : Boolean(item.is_active),
      order:
        item.order !== null && item.order !== undefined
          ? Number(item.order)
          : 0,
    });

    setShowForm(true);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const handleChange = (event) => {
    const { name, value, type, checked } = event.target;

    setFormData((previous) => ({
      ...previous,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const buildPayload = () => {
    return {
      name_en: formData.name_en.trim(),
      name_km: formData.name_km.trim() || null,

      role_en: formData.role_en.trim() || null,
      role_km: formData.role_km.trim() || null,

      company_en: formData.company_en.trim() || null,
      company_km: formData.company_km.trim() || null,

      story_en: formData.story_en.trim() || null,
      story_km: formData.story_km.trim() || null,

      image: formData.image.trim() || null,

      graduation_year:
        formData.graduation_year === ""
          ? null
          : Number(formData.graduation_year),

      is_featured: Boolean(formData.is_featured),
      is_active: Boolean(formData.is_active),
      order: Number(formData.order) || 0,
    };
  };

  const validateForm = () => {
    if (!formData.name_en.trim()) {
      showMessage("error", tr("alumni.nameRequired", "English name is required.", "សូមបញ្ចូលឈ្មោះជាភាសាអង់គ្លេស។"));
      return false;
    }

    if (
      formData.graduation_year !== "" &&
      (!Number.isInteger(Number(formData.graduation_year)) ||
        Number(formData.graduation_year) < 1900 ||
        Number(formData.graduation_year) > 2100)
    ) {
      showMessage(
        "error",
        tr("alumni.invalidGraduationYear", "Graduation year must be between 1900 and 2100.", "ឆ្នាំបញ្ចប់ការសិក្សាត្រូវស្ថិតចន្លោះឆ្នាំ 1900 និង 2100។")
      );
      return false;
    }

    return true;
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (!validateForm()) return;

    try {
      setSaving(true);

      const payload = buildPayload();

      if (editingId) {
        await api.put(`/api/alumni/${editingId}`, payload);
        showMessage("success", tr("alumni.updatedSuccess", "Alumni updated successfully.", "បានកែប្រែព័ត៌មានអតីតសិស្សដោយជោគជ័យ។"));
      } else {
        await api.post("/api/alumni/", payload);
        showMessage("success", tr("alumni.createdSuccess", "Alumni created successfully.", "បានបង្កើតព័ត៌មានអតីតសិស្សដោយជោគជ័យ។"));
      }

      resetForm();
      await fetchAlumni();
    } catch (error) {
      console.error("Save alumni error:", error);
      showMessage("error", getApiErrorMessage(error));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (item) => {
    const displayName =
      localized(
        item,
        "name",
        item.name_en || item.name_km || ""
      ) ||
      tr(
        "alumni.thisAlumni",
        "this alumni",
        "អតីតសិស្សនេះ"
      );

    const confirmed = window.confirm(
      tr(
        "alumni.deleteConfirm",
        `Delete "${displayName}"?`,
        `តើអ្នកប្រាកដថាចង់លុប "${displayName}" មែនទេ?`
      )
    );

    if (!confirmed) return;

    try {
      setDeletingId(item.id);

      await api.delete(`/api/alumni/${item.id}`);

      showMessage("success", tr("alumni.deletedSuccess", "Alumni deleted successfully.", "បានលុបព័ត៌មានអតីតសិស្សដោយជោគជ័យ។"));
      await fetchAlumni();
    } catch (error) {
      console.error("Delete alumni error:", error);
      showMessage("error", getApiErrorMessage(error));
    } finally {
      setDeletingId(null);
    }
  };

  const handleQuickUpdate = async (item, field) => {
    try {
      const payload = {
        [field]: !item[field],
      };

      await api.put(`/api/alumni/${item.id}`, payload);

      setAlumni((previous) =>
        previous.map((record) =>
          record.id === item.id
            ? {
                ...record,
                ...payload,
              }
            : record
        )
      );

      showMessage(
        "success",
        field === "is_active"
          ? tr("alumni.statusUpdated", "Status updated.", "បានធ្វើបច្ចុប្បន្នភាពស្ថានភាព។")
          : tr("alumni.featuredUpdated", "Featured status updated.", "បានធ្វើបច្ចុប្បន្នភាពស្ថានភាពពិសេស។")
      );
    } catch (error) {
      console.error("Quick update alumni error:", error);
      showMessage("error", getApiErrorMessage(error));
    }
  };

  return (
    <main className={`min-h-screen bg-slate-50 px-4 py-6 md:px-6 lg:px-8 ${isKhmer ? "font-khmer" : "font-english"}`}>
      <div className="mx-auto w-full max-w-[1450px]">
        {/* =====================================================
            HEADER
        ====================================================== */}
        <section className="mb-6 overflow-hidden rounded-2xl bg-[#0B1849] text-white shadow-sm">
          <div className="relative px-5 py-6 md:px-8 md:py-8">
            <div className="pointer-events-none absolute -right-20 -top-24 h-64 w-64 rounded-full bg-red-600/10 blur-3xl" />
            <div className="pointer-events-none absolute -bottom-24 left-20 h-56 w-56 rounded-full bg-white/5 blur-3xl" />

            <div className="relative z-10 flex flex-col gap-5 md:flex-row md:items-center md:justify-between">
              <div>
                <div className="mb-2 flex items-center gap-2 text-red-400">
                  <span className="h-[2px] w-7 rounded-full bg-red-500" />
                  <span className="text-[11px] font-bold uppercase tracking-[0.18em]">
                    {tr("admin.panel", "SC Academy Admin", "ផ្ទាំងអ្នកគ្រប់គ្រង SC Academy")}
                  </span>
                </div>

                <h1 className="text-[28px] font-bold md:text-[36px]">
                  {tr("alumni.management", "Alumni Management", "គ្រប់គ្រងអតីតសិស្ស")}
                </h1>

                <p className="mt-2 max-w-2xl text-[13px] leading-6 text-white/65">
                  {tr("alumni.subtitle", "Create, update and manage alumni profiles shown on the SC Academy website.", "បង្កើត កែប្រែ និងគ្រប់គ្រងព័ត៌មានអតីតសិស្សដែលបង្ហាញលើគេហទំព័រ SC Academy។")}
                </p>
              </div>

              <button
                type="button"
                onClick={openCreateForm}
                className="inline-flex h-[44px] items-center justify-center gap-2 rounded-lg bg-red-600 px-6 text-[12px] font-bold text-white shadow-sm transition hover:bg-red-700"
              >
                <FiPlus size={16} />
                {tr("alumni.addAlumni", "Add Alumni", "បន្ថែមអតីតសិស្ស")}
              </button>
            </div>
          </div>
        </section>

        {/* =====================================================
            MESSAGE
        ====================================================== */}
        {message.text && (
          <div
            className={`mb-5 flex items-center justify-between rounded-xl border px-4 py-3 text-[12px] font-semibold ${
              message.type === "success"
                ? "border-emerald-200 bg-emerald-50 text-emerald-700"
                : "border-red-200 bg-red-50 text-red-700"
            }`}
          >
            <div className="flex items-center gap-2">
              {message.type === "success" ? (
                <FiCheck size={16} />
              ) : (
                <FiX size={16} />
              )}
              {message.text}
            </div>

            <button
              type="button"
              onClick={() => setMessage({ type: "", text: "" })}
              className="rounded-md p-1 transition hover:bg-black/5"
              aria-label={tr("common.close", "Close", "បិទ")}
            >
              <FiX />
            </button>
          </div>
        )}

        {/* =====================================================
            STATS
        ====================================================== */}
        <section className="mb-6 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
          {[
            {
              title: tr("alumni.totalAlumni", "Total Alumni", "អតីតសិស្សសរុប"),
              value: stats.total,
              icon: FiUser,
            },
            {
              title: tr("common.active", "Active", "សកម្ម"),
              value: stats.active,
              icon: FiCheck,
            },
            {
              title: tr("common.featured", "Featured", "ពិសេស"),
              value: stats.featured,
              icon: FiStar,
            },
            {
              title: tr("common.inactive", "Inactive", "អសកម្ម"),
              value: stats.inactive,
              icon: FiX,
            },
          ].map((stat) => {
            const Icon = stat.icon;

            return (
              <article
                key={stat.title}
                className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"
              >
                <div className="flex items-center justify-between gap-4">
                  <div>
                    <p className="text-[11px] font-semibold uppercase tracking-[0.12em] text-slate-500">
                      {stat.title}
                    </p>

                    <p className="mt-2 text-[28px] font-bold text-blue-950">
                      {stat.value}
                    </p>
                  </div>

                  <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-blue-50 text-blue-900">
                    <Icon size={20} />
                  </div>
                </div>
              </article>
            );
          })}
        </section>

        {/* =====================================================
            FORM
        ====================================================== */}
        {showForm && (
          <section className="mb-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
            <div className="flex items-center justify-between gap-4 border-b border-slate-200 px-5 py-4 md:px-6">
              <div>
                <p className="text-[10px] font-bold uppercase tracking-[0.15em] text-red-600">
                  {tr("alumni.form", "Alumni Form", "ទម្រង់ព័ត៌មានអតីតសិស្ស")}
                </p>

                <h2 className="mt-1 text-[19px] font-bold text-blue-950">
                  {editingId ? tr("alumni.editAlumni", "Edit Alumni", "កែប្រែអតីតសិស្ស") : tr("alumni.createAlumni", "Create Alumni", "បង្កើតអតីតសិស្ស")}
                </h2>
              </div>

              <button
                type="button"
                onClick={resetForm}
                disabled={saving}
                className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 text-slate-500 transition hover:border-red-500 hover:bg-red-50 hover:text-red-600"
                aria-label={tr("common.close", "Close", "បិទ")}
              >
                <FiX size={17} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-5 md:p-6">
              <div className="grid grid-cols-1 gap-6 xl:grid-cols-[1fr_320px]">
                <div className="space-y-6">
                  {/* ENGLISH */}
                  <fieldset className="rounded-2xl border border-slate-200 p-4 md:p-5">
                    <legend className="px-2 text-[12px] font-bold text-blue-950">
                      {tr("alumni.englishInformation", "English Information", "ព័ត៌មានជាភាសាអង់គ្លេស")}
                    </legend>

                    <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                      <InputField
                        label={tr("common.name", "Name", "ឈ្មោះ")}
                        name="name_en"
                        value={formData.name_en}
                        onChange={handleChange}
                        required
                        placeholder={tr("alumni.namePlaceholder", "Alumni full name", "ឈ្មោះពេញរបស់អតីតសិស្ស")}
                      />

                      <InputField
                        label={tr("alumni.rolePosition", "Role / Position", "តួនាទី / មុខតំណែង")}
                        name="role_en"
                        value={formData.role_en}
                        onChange={handleChange}
                        placeholder={tr("alumni.rolePlaceholder", "Software Developer", "អ្នកអភិវឌ្ឍន៍កម្មវិធី")}
                      />

                      <InputField
                        label={tr("alumni.companyInstitution", "Company / Institution", "ក្រុមហ៊ុន / ស្ថាប័ន")}
                        name="company_en"
                        value={formData.company_en}
                        onChange={handleChange}
                        placeholder={tr("alumni.companyPlaceholder", "Company or university", "ក្រុមហ៊ុន ឬសាកលវិទ្យាល័យ")}
                        wrapperClassName="md:col-span-2"
                      />

                      <TextareaField
                        label={tr("alumni.story", "Story", "រឿងរ៉ាវជោគជ័យ")}
                        name="story_en"
                        value={formData.story_en}
                        onChange={handleChange}
                        placeholder={tr("alumni.storyPlaceholder", "Write the alumni success story...", "សរសេរអំពីរឿងរ៉ាវជោគជ័យរបស់អតីតសិស្ស...")}
                        wrapperClassName="md:col-span-2"
                      />
                    </div>
                  </fieldset>

                  {/* KHMER */}
                  <fieldset className="rounded-2xl border border-slate-200 p-4 md:p-5 font-khmer">
                    <legend className="px-2 text-[12px] font-bold text-blue-950">
                      {tr("alumni.khmerInformation", "Khmer Information", "ព័ត៌មានជាភាសាខ្មែរ")}
                    </legend>

                    <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                      <InputField
                        label={tr("common.name", "Name", "ឈ្មោះ")}
                        name="name_km"
                        value={formData.name_km}
                        onChange={handleChange}
                        placeholder={tr("alumni.nameKhmerPlaceholder", "Alumni name in Khmer", "ឈ្មោះអតីតសិស្សជាភាសាខ្មែរ")}
                      />

                      <InputField
                        label={tr("alumni.rolePosition", "Role / Position", "តួនាទី / មុខតំណែង")}
                        name="role_km"
                        value={formData.role_km}
                        onChange={handleChange}
                        placeholder={tr("alumni.roleKhmerPlaceholder", "Role in Khmer", "តួនាទីជាភាសាខ្មែរ")}
                      />

                      <InputField
                        label={tr("alumni.companyInstitution", "Company / Institution", "ក្រុមហ៊ុន / ស្ថាប័ន")}
                        name="company_km"
                        value={formData.company_km}
                        onChange={handleChange}
                        placeholder={tr("alumni.companyKhmerPlaceholder", "Company or institution in Khmer", "ក្រុមហ៊ុន ឬស្ថាប័នជាភាសាខ្មែរ")}
                        wrapperClassName="md:col-span-2"
                      />

                      <TextareaField
                        label={tr("alumni.story", "Story", "រឿងរ៉ាវជោគជ័យ")}
                        name="story_km"
                        value={formData.story_km}
                        onChange={handleChange}
                        placeholder={tr("alumni.storyKhmerPlaceholder", "Success story in Khmer...", "សរសេរអំពីរឿងរ៉ាវជោគជ័យរបស់អតីតសិស្សជាភាសាខ្មែរ...")}
                        wrapperClassName="md:col-span-2"
                      />
                    </div>
                  </fieldset>

                  {/* SETTINGS */}
                  <fieldset className="rounded-2xl border border-slate-200 p-4 md:p-5">
                    <legend className="px-2 text-[12px] font-bold text-blue-950">
                      {tr("alumni.displaySettings", "Display Settings", "ការកំណត់ការបង្ហាញ")}
                    </legend>

                    <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
                      <InputField
                        label={tr("alumni.graduationYear", "Graduation Year", "ឆ្នាំបញ្ចប់ការសិក្សា")}
                        name="graduation_year"
                        type="number"
                        min="1900"
                        max="2100"
                        value={formData.graduation_year}
                        onChange={handleChange}
                        placeholder="2024"
                      />

                      <InputField
                        label={tr("alumni.displayOrder", "Display Order", "លំដាប់បង្ហាញ")}
                        name="order"
                        type="number"
                        min="0"
                        value={formData.order}
                        onChange={handleChange}
                        placeholder="0"
                      />

                      <div className="flex flex-col justify-end gap-3 rounded-xl bg-slate-50 p-4">
                        <CheckboxField
                          label={tr("common.active", "Active", "សកម្ម")}
                          name="is_active"
                          checked={formData.is_active}
                          onChange={handleChange}
                        />

                        <CheckboxField
                          label={tr("alumni.featuredOnHome", "Featured on Home", "បង្ហាញពិសេសលើទំព័រដើម")}
                          name="is_featured"
                          checked={formData.is_featured}
                          onChange={handleChange}
                        />
                      </div>
                    </div>
                  </fieldset>
                </div>

                {/* IMAGE */}
                <aside className="space-y-4">
                  <div className="rounded-2xl border border-slate-200 p-4">
                    <label
                      htmlFor="image"
                      className="mb-2 block text-[11px] font-bold text-blue-950"
                    >
                      {tr("alumni.imagePath", "Image URL / Upload Path", "តំណរូបភាព / ទីតាំងឯកសារ")}
                    </label>

                    <input
                      id="image"
                      name="image"
                      type="text"
                      value={formData.image}
                      onChange={handleChange}
                      placeholder="/uploads/alumni/photo.jpg"
                      className="h-[44px] w-full rounded-lg border border-slate-200 bg-slate-50 px-3 text-[12px] text-slate-900 outline-none transition focus:border-blue-900 focus:bg-white focus:ring-2 focus:ring-blue-900/5"
                    />

                    <p className="mt-2 text-[10px] leading-5 text-slate-500">
                      {tr("alumni.imageHelp", "Use a complete URL or a backend upload path such as", "ប្រើតំណពេញ ឬទីតាំងឯកសារពី Backend ដូចជា")}
                      <code className="ml-1 rounded bg-slate-100 px-1 py-0.5">
                        /uploads/alumni/photo.jpg
                      </code>
                    </p>
                  </div>

                  <div className="overflow-hidden rounded-2xl border border-slate-200 bg-slate-100">
                    <div className="relative flex aspect-[4/5] items-center justify-center">
                      {formData.image ? (
                        <img
                          src={getImageUrl(formData.image)}
                          alt="Alumni preview"
                          className="absolute inset-0 h-full w-full object-cover"
                          onError={(event) => {
                            event.currentTarget.style.display = "none";
                          }}
                        />
                      ) : null}

                      <div className="flex flex-col items-center justify-center text-slate-400">
                        <FiImage size={34} />
                        <span className="mt-2 text-[11px] font-semibold">
                          {tr("alumni.imagePreview", "Image Preview", "មើលរូបភាពជាមុន")}
                        </span>
                      </div>
                    </div>
                  </div>
                </aside>
              </div>

              <div className="mt-6 flex flex-col-reverse gap-3 border-t border-slate-200 pt-5 sm:flex-row sm:justify-end">
                <button
                  type="button"
                  onClick={resetForm}
                  disabled={saving}
                  className="inline-flex h-[44px] items-center justify-center rounded-lg border border-slate-200 bg-white px-6 text-[12px] font-bold text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {tr("common.cancel", "Cancel", "បោះបង់")}
                </button>

                <button
                  type="submit"
                  disabled={saving}
                  className="inline-flex h-[44px] items-center justify-center gap-2 rounded-lg bg-red-600 px-7 text-[12px] font-bold text-white shadow-sm transition hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {saving ? (
                    <>
                      <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />
                      {tr("common.saving", "Saving...", "កំពុងរក្សាទុក...")}
                    </>
                  ) : (
                    <>
                      <FiCheck size={15} />
                      {editingId ? tr("alumni.updateAlumni", "Update Alumni", "ធ្វើបច្ចុប្បន្នភាពអតីតសិស្ស") : tr("alumni.createAlumni", "Create Alumni", "បង្កើតអតីតសិស្ស")}
                    </>
                  )}
                </button>
              </div>
            </form>
          </section>
        )}

        {/* =====================================================
            FILTERS
        ====================================================== */}
        <section className="mb-5 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
          <div className="grid grid-cols-1 gap-3 md:grid-cols-[1fr_180px_180px_auto]">
            <div className="relative">
              <FiSearch
                size={15}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
              />

              <input
                type="search"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder={tr("alumni.searchPlaceholder", "Search alumni...", "ស្វែងរកអតីតសិស្ស...")}
                className="h-[42px] w-full rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 text-[12px] outline-none transition focus:border-blue-900 focus:bg-white"
              />
            </div>

            <select
              value={statusFilter}
              onChange={(event) => setStatusFilter(event.target.value)}
              className="h-[42px] rounded-lg border border-slate-200 bg-slate-50 px-3 text-[12px] font-semibold text-slate-700 outline-none focus:border-blue-900"
            >
              <option value="all">{tr("alumni.allStatus", "All Status", "ស្ថានភាពទាំងអស់")}</option>
              <option value="active">{tr("common.active", "Active", "សកម្ម")}</option>
              <option value="inactive">{tr("common.inactive", "Inactive", "អសកម្ម")}</option>
            </select>

            <select
              value={featuredFilter}
              onChange={(event) => setFeaturedFilter(event.target.value)}
              className="h-[42px] rounded-lg border border-slate-200 bg-slate-50 px-3 text-[12px] font-semibold text-slate-700 outline-none focus:border-blue-900"
            >
              <option value="all">{tr("alumni.allAlumni", "All Alumni", "អតីតសិស្សទាំងអស់")}</option>
              <option value="featured">{tr("common.featured", "Featured", "ពិសេស")}</option>
              <option value="regular">{tr("alumni.notFeatured", "Not Featured", "មិនពិសេស")}</option>
            </select>

            <button
              type="button"
              onClick={fetchAlumni}
              disabled={loading}
              className="inline-flex h-[42px] items-center justify-center gap-2 rounded-lg border border-slate-200 bg-white px-4 text-[11px] font-bold text-blue-900 transition hover:border-blue-900 hover:bg-blue-50 disabled:opacity-60"
            >
              <FiRefreshCw
                size={14}
                className={loading ? "animate-spin" : ""}
              />
              {tr("common.refresh", "Refresh", "ផ្ទុកឡើងវិញ")}
            </button>
          </div>
        </section>

        {/* =====================================================
            LIST
        ====================================================== */}
        <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="flex flex-col gap-2 border-b border-slate-200 px-5 py-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-[0.15em] text-red-600">
                {tr("alumni.directory", "Alumni Directory", "បញ្ជីអតីតសិស្ស")}
              </p>

              <h2 className="mt-1 text-[18px] font-bold text-blue-950">
                {tr("alumni.records", "Alumni Records", "កំណត់ត្រាអតីតសិស្ស")}
              </h2>
            </div>

            <p className="text-[11px] font-semibold text-slate-500">
              {tr("alumni.showing", "Showing", "កំពុងបង្ហាញ")} {filteredAlumni.length} {tr("alumni.of", "of", "ក្នុងចំណោម")} {alumni.length}
            </p>
          </div>

          {loading ? (
            <div className="flex min-h-[280px] items-center justify-center">
              <div className="text-center">
                <span className="mx-auto block h-8 w-8 animate-spin rounded-full border-4 border-slate-200 border-t-blue-900" />
                <p className="mt-3 text-[12px] font-semibold text-slate-500">
                  {tr("alumni.loading", "Loading alumni...", "កំពុងផ្ទុកអតីតសិស្ស...")}
                </p>
              </div>
            </div>
          ) : filteredAlumni.length === 0 ? (
            <div className="flex min-h-[280px] flex-col items-center justify-center px-5 text-center">
              <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-blue-50 text-blue-900">
                <FiAward size={25} />
              </div>

              <h3 className="mt-4 text-[17px] font-bold text-blue-950">
                {tr("alumni.noAlumni", "No Alumni Found", "រកមិនឃើញអតីតសិស្ស")}
              </h3>

              <p className="mt-2 max-w-sm text-[12px] leading-6 text-slate-500">
                {tr("alumni.noAlumniDescription", "Add the first alumni profile or change your filters.", "សូមបន្ថែមអតីតសិស្សដំបូង ឬកែប្រែតម្រងស្វែងរក។")}
              </p>

              <button
                type="button"
                onClick={openCreateForm}
                className="mt-5 inline-flex h-[42px] items-center justify-center gap-2 rounded-lg bg-red-600 px-5 text-[11px] font-bold text-white transition hover:bg-red-700"
              >
                <FiPlus />
                {tr("alumni.addAlumni", "Add Alumni", "បន្ថែមអតីតសិស្ស")}
              </button>
            </div>
          ) : (
            <>
              {/* Desktop table */}
              <div className="hidden overflow-x-auto lg:block">
                <table className="w-full min-w-[1050px] border-collapse">
                  <thead>
                    <tr className="bg-slate-50 text-left">
                      {[
                        "Alumni",
                        "Role & Company",
                        "Graduation",
                        "Order",
                        tr("common.featured", "Featured", "ពិសេស"),
                        "Status",
                        "Actions",
                      ].map((heading) => (
                        <th
                          key={heading}
                          className="border-b border-slate-200 px-4 py-3 text-[10px] font-bold uppercase tracking-[0.1em] text-slate-500"
                        >
                          {heading}
                        </th>
                      ))}
                    </tr>
                  </thead>

                  <tbody>
                    {filteredAlumni.map((item) => (
                      <tr
                        key={item.id}
                        className="border-b border-slate-100 transition last:border-b-0 hover:bg-slate-50/70"
                      >
                        <td className="px-4 py-4">
                          <div className="flex min-w-[230px] items-center gap-3">
                            <div className="relative h-12 w-12 flex-none overflow-hidden rounded-xl bg-slate-100">
                              {item.image ? (
                                <img
                                  src={getImageUrl(item.image)}
                                  alt={localized(item, "name", tr("alumni.alumni", "Alumni", "អតីតសិស្ស"))}
                                  className="h-full w-full object-cover"
                                  onError={(event) => {
                                    event.currentTarget.style.display =
                                      "none";
                                  }}
                                />
                              ) : null}

                              <div className="absolute inset-0 -z-10 flex items-center justify-center text-slate-400">
                                <FiUser size={19} />
                              </div>
                            </div>

                            <div className="min-w-0">
                              <p className="truncate text-[13px] font-bold text-blue-950">
                                {localized(item, "name", "—")}
                              </p>

                              <p className="mt-1 truncate text-[11px] text-slate-500 font-khmer">
                                {isKhmer ? item.name_en || "—" : item.name_km || "—"}
                              </p>
                            </div>
                          </div>
                        </td>

                        <td className="px-4 py-4">
                          <div className="max-w-[260px]">
                            <p className="truncate text-[12px] font-semibold text-slate-800">
                              {localized(item, "role", "—")}
                            </p>

                            <p className="mt-1 truncate text-[11px] text-slate-500">
                              {localized(item, "company", "—")}
                            </p>
                          </div>
                        </td>

                        <td className="px-4 py-4 text-[12px] font-semibold text-slate-700">
                          {item.graduation_year || "—"}
                        </td>

                        <td className="px-4 py-4 text-[12px] font-semibold text-slate-700">
                          {item.order ?? 0}
                        </td>

                        <td className="px-4 py-4">
                          <button
                            type="button"
                            onClick={() =>
                              handleQuickUpdate(item, "is_featured")
                            }
                            className={`inline-flex h-8 items-center gap-1.5 rounded-full px-3 text-[10px] font-bold transition ${
                              item.is_featured
                                ? "bg-amber-100 text-amber-700 hover:bg-amber-200"
                                : "bg-slate-100 text-slate-500 hover:bg-slate-200"
                            }`}
                          >
                            <FiStar
                              size={12}
                              className={
                                item.is_featured ? "fill-current" : ""
                              }
                            />
                            {item.is_featured
                              ? tr("common.featured", "Featured", "ពិសេស")
                              : "Regular"}
                          </button>
                        </td>

                        <td className="px-4 py-4">
                          <button
                            type="button"
                            onClick={() =>
                              handleQuickUpdate(item, "is_active")
                            }
                            className={`inline-flex h-8 items-center rounded-full px-3 text-[10px] font-bold transition ${
                              item.is_active
                                ? "bg-emerald-100 text-emerald-700 hover:bg-emerald-200"
                                : "bg-red-100 text-red-700 hover:bg-red-200"
                            }`}
                          >
                            {item.is_active ? tr("common.active", "Active", "សកម្ម") : tr("common.inactive", "Inactive", "អសកម្ម")}
                          </button>
                        </td>

                        <td className="px-4 py-4">
                          <div className="flex items-center gap-2">
                            <button
                              type="button"
                              onClick={() => openEditForm(item)}
                              className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 bg-white text-blue-900 transition hover:border-blue-900 hover:bg-blue-50"
                              aria-label={`Edit ${item.name_en}`}
                              title={tr("common.edit", "Edit", "កែប្រែ")}
                            >
                              <FiEdit2 size={14} />
                            </button>

                            <button
                              type="button"
                              onClick={() => handleDelete(item)}
                              disabled={deletingId === item.id}
                              className="flex h-9 w-9 items-center justify-center rounded-lg border border-red-200 bg-red-50 text-red-600 transition hover:bg-red-600 hover:text-white disabled:cursor-not-allowed disabled:opacity-60"
                              aria-label={`Delete ${item.name_en}`}
                              title={tr("common.delete", "Delete", "លុប")}
                            >
                              {deletingId === item.id ? (
                                <span className="h-4 w-4 animate-spin rounded-full border-2 border-red-300 border-t-red-600" />
                              ) : (
                                <FiTrash2 size={14} />
                              )}
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Mobile / tablet cards */}
              <div className="grid grid-cols-1 gap-4 p-4 sm:grid-cols-2 lg:hidden">
                {filteredAlumni.map((item) => (
                  <article
                    key={item.id}
                    className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"
                  >
                    <div className="relative h-[210px] bg-slate-100">
                      {item.image ? (
                        <img
                          src={getImageUrl(item.image)}
                          alt={localized(item, "name", tr("alumni.alumni", "Alumni", "អតីតសិស្ស"))}
                          className="h-full w-full object-cover"
                          onError={(event) => {
                            event.currentTarget.style.display = "none";
                          }}
                        />
                      ) : (
                        <div className="flex h-full items-center justify-center text-slate-300">
                          <FiUser size={42} />
                        </div>
                      )}

                      <div className="absolute inset-0 bg-gradient-to-t from-blue-950/75 via-transparent to-transparent" />

                      <div className="absolute left-3 top-3 flex gap-2">
                        {item.is_featured && (
                          <span className="rounded-full bg-amber-400 px-2.5 py-1 text-[9px] font-bold text-amber-950">
                            Featured
                          </span>
                        )}

                        <span
                          className={`rounded-full px-2.5 py-1 text-[9px] font-bold ${
                            item.is_active
                              ? "bg-emerald-500 text-white"
                              : "bg-red-500 text-white"
                          }`}
                        >
                          {item.is_active ? tr("common.active", "Active", "សកម្ម") : tr("common.inactive", "Inactive", "អសកម្ម")}
                        </span>
                      </div>

                      <div className="absolute inset-x-0 bottom-0 p-4 text-white">
                        <h3 className="text-[16px] font-bold">
                          {localized(item, "name", tr("alumni.alumni", "Alumni", "អតីតសិស្ស"))}
                        </h3>

                        <p className="mt-1 text-[11px] text-white/75 font-khmer">
                          {isKhmer ? item.name_en || "" : item.name_km || ""}
                        </p>
                      </div>
                    </div>

                    <div className="p-4">
                      <p className="text-[12px] font-semibold text-red-600">
                        {localized(item, "role", "—")}
                      </p>

                      <p className="mt-1 text-[11px] text-slate-500">
                        {localized(item, "company", "—")}
                      </p>

                      <div className="mt-4 flex items-center justify-between border-t border-slate-200 pt-4">
                        <span className="text-[10px] font-semibold text-slate-500">
                          {tr("alumni.graduation", "Graduation", "ឆ្នាំបញ្ចប់ការសិក្សា")}: {item.graduation_year || "—"}
                        </span>

                        <div className="flex gap-2">
                          <button
                            type="button"
                            onClick={() => openEditForm(item)}
                            className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 text-blue-900"
                          >
                            <FiEdit2 size={14} />
                          </button>

                          <button
                            type="button"
                            onClick={() => handleDelete(item)}
                            disabled={deletingId === item.id}
                            className="flex h-9 w-9 items-center justify-center rounded-lg border border-red-200 bg-red-50 text-red-600 disabled:opacity-60"
                          >
                            {deletingId === item.id ? (
                              <span className="h-4 w-4 animate-spin rounded-full border-2 border-red-300 border-t-red-600" />
                            ) : (
                              <FiTrash2 size={14} />
                            )}
                          </button>
                        </div>
                      </div>
                    </div>
                  </article>
                ))}
              </div>
            </>
          )}
        </section>
      </div>
    </main>
  );
};

const InputField = ({
  label,
  name,
  value,
  onChange,
  type = "text",
  required = false,
  placeholder = "",
  min,
  max,
  wrapperClassName = "",
}) => {
  return (
    <div className={wrapperClassName}>
      <label
        htmlFor={name}
        className="mb-1.5 block text-[11px] font-bold text-blue-950"
      >
        {label}
        {required && <span className="ml-1 text-red-600">*</span>}
      </label>

      <input
        id={name}
        name={name}
        type={type}
        value={value}
        onChange={onChange}
        required={required}
        placeholder={placeholder}
        min={min}
        max={max}
        className="h-[44px] w-full rounded-lg border border-slate-200 bg-slate-50 px-3 text-[12px] text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-900 focus:bg-white focus:ring-2 focus:ring-blue-900/5"
      />
    </div>
  );
};

const TextareaField = ({
  label,
  name,
  value,
  onChange,
  placeholder = "",
  wrapperClassName = "",
}) => {
  return (
    <div className={wrapperClassName}>
      <label
        htmlFor={name}
        className="mb-1.5 block text-[11px] font-bold text-blue-950"
      >
        {label}
      </label>

      <textarea
        id={name}
        name={name}
        value={value}
        onChange={onChange}
        rows={5}
        placeholder={placeholder}
        className="min-h-[130px] w-full resize-y rounded-lg border border-slate-200 bg-slate-50 px-3 py-3 text-[12px] leading-6 text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-900 focus:bg-white focus:ring-2 focus:ring-blue-900/5"
      />
    </div>
  );
};

const CheckboxField = ({
  label,
  name,
  checked,
  onChange,
}) => {
  return (
    <label
      htmlFor={name}
      className="flex cursor-pointer items-center justify-between gap-4"
    >
      <span className="text-[11px] font-bold text-slate-700">
        {label}
      </span>

      <span className="relative inline-flex">
        <input
          id={name}
          name={name}
          type="checkbox"
          checked={checked}
          onChange={onChange}
          className="peer sr-only"
        />

        <span className="h-6 w-11 rounded-full bg-slate-300 transition peer-checked:bg-blue-900" />

        <span className="absolute left-1 top-1 h-4 w-4 rounded-full bg-white shadow-sm transition peer-checked:translate-x-5" />
      </span>
    </label>
  );
};

export default AdminAlumni;
